package com.testforge.testforge_backend.testsuite.entity;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="suite_test_step_result") public class SuiteTestStepResult {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="test_case_result_id") private SuiteTestCaseResult testCaseResult; @Column(name="source_test_step_id") private Long sourceTestStepId; @Column(name="test_step_business_id_snapshot",nullable=false) private String testStepBusinessIdSnapshot; @Column(name="action_snapshot",nullable=false,length=1000) private String actionSnapshot; @Column(name="expected_result_snapshot",length=2000) private String expectedResultSnapshot; @Column(name="step_order",nullable=false) private Integer stepOrder; @Enumerated(EnumType.STRING) @Column(nullable=false) private SuiteResultStatus status=SuiteResultStatus.PENDING; @Column(name="started_at") private LocalDateTime startedAt; @Column(name="completed_at") private LocalDateTime completedAt; @Column(name="duration_ms") private Long durationMs; @Column(name="failure_details",columnDefinition="text") private String failureDetails; @Column(name="screenshot_path") private String screenshotPath; @Column(name="artifact_reference") private String artifactReference;
 public SuiteTestStepResult(){} public SuiteTestStepResult(Long id,String businessId,String action,String expected,Integer order){sourceTestStepId=id;testStepBusinessIdSnapshot=businessId;actionSnapshot=action;expectedResultSnapshot=expected;stepOrder=order;} void setTestCaseResult(SuiteTestCaseResult v){testCaseResult=v;} public Integer getStepOrder(){return stepOrder;} public SuiteResultStatus getStatus(){return status;} public String getTestStepBusinessIdSnapshot(){return testStepBusinessIdSnapshot;} public String getActionSnapshot(){return actionSnapshot;} public String getFailureDetails(){return failureDetails;} public String getScreenshotPath(){return screenshotPath;} public String getArtifactReference(){return artifactReference;}
 void finish(SuiteResultStatus caseStatus,Integer failedOrder,String error,String screenshot,String artifact){if(caseStatus==SuiteResultStatus.PASSED)status=SuiteResultStatus.PASSED;else if(failedOrder!=null&&stepOrder.equals(failedOrder)){status=SuiteResultStatus.FAILED;failureDetails=error;screenshotPath=screenshot;artifactReference=artifact;}else if(failedOrder!=null&&stepOrder<failedOrder)status=SuiteResultStatus.PASSED;else status=SuiteResultStatus.SKIPPED;} void skip(){status=SuiteResultStatus.SKIPPED;}
}
